def compute(vars):
    less_than_1_year = vars["v1"]
    years_1_to_3 = vars["v2"]
    total_within_3_years = less_than_1_year + years_1_to_3

    return {
        "value": total_within_3_years,
        "trace": {
            "less_than_1_year": less_than_1_year,
            "years_1_to_3": years_1_to_3,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None,
            },
        },
    }
